class Solution {
public:
    int climbStairs(int n, vector<int>& costs) {
        const long long INF = (1LL<<60);
        long long dp[4];
        dp[0] = 0;                     // dp for step 0
        dp[1] = dp[2] = dp[3] = INF;   // placeholders

        for (int j = 1; j <= n; ++j) {
            long long best = INF;
            for (int k = 1; k <= 3; ++k) {
                if (j - k < 0) continue;
                long long prev = dp[(j - k) % 4];
                long long cand = prev + costs[j - 1] + 1LL * k * k;
                if (cand < best) best = cand;
            }
            dp[j % 4] = best;
        }
        return static_cast<int>(dp[n % 4]);
    }
};
